task.vi:
Viết chương trình hiển thị mẫu bàn cờ 8x8 gồm các dấu sao. Chương trình chỉ được sử dụng đúng ba lệnh xuất riêng biệt sau:
cout << "* ";
cout << ' ';
cout << endl;
Mẫu in ra có dạng các hàng so le dấu cách thụt lề ở các hàng chẵn.

task.en:
Write a program that displays the 8x8 checkerboard pattern of asterisks. Your program must use only three output statements, one of each of the following forms:
cout << "* ";
cout << ' ';
cout << endl;

example.code:
#include <iostream>

int main() {
    int x{0};
    int y{0};
    if (!(std::cin >> x >> y)) {
        return 0;
    }

    // Truong hop 1: Khong dung ngoac - else tu dong ghep vao 'y > 10'
    std::cout << "Case 1:" << std::endl;
    if (x < 10)
        if (y > 10)
            std::cout << "*****" << std::endl;
        else
            std::cout << "#####" << std::endl;
    std::cout << "$$$$$" << std::endl;

    // Truong hop 2: Co ngoac tuong minh - else thuoc ve 'x < 10'
    std::cout << "Case 2:" << std::endl;
    if (x < 10) {
        if (y > 10) {
            std::cout << "*****" << std::endl;
        }
    } else {
        std::cout << "#####" << std::endl;
        std::cout << "$$$$$" << std::endl;
    }

    return 0;
}

#include <iostream>

int main() {
    int binaryInput{0};
    if (!(std::cin >> binaryInput)) {
        return 0;
    }

    int decimalSum{0};
    int weight{1};
    int temp{binaryInput};

    while (temp > 0) {
        int digit{temp % 10};
        decimalSum += digit * weight;
        weight *= 2;
        temp /= 10;
    }

    std::cout << "Binary: " << binaryInput << " -> Decimal: " << decimalSum << std::endl;
    return 0;
}

